using Pxxl.Blazor.Components;var builder=WebApplication.CreateBuilder(args);builder.Services.AddRazorComponents().AddInteractiveServerComponents();var app=builder.Build();app.UseStaticFiles();app.MapGet("/health",()=>Results.Ok(new{status="ok"}));app.MapGet("/api",()=>Results.Ok(new{message="Hello from Blazor"}));app.MapRazorComponents<App>().AddInteractiveServerRenderMode();app.Run();
